#include <cstdio>
#include <vector>
#include <queue>
#include <functional>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    std::vector<std::vector<int>> adj(n + 1);
    std::vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        indeg[v]++;
    }

    std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
    for (int i = 1; i <= n; ++i) if (indeg[i] == 0) pq.push(i);

    std::vector<int> res;
    while (!pq.empty()) {
        int u = pq.top(); pq.pop();
        res.push_back(u);
        for (int v : adj[u]) {
            if (--indeg[v] == 0) pq.push(v);
        }
    }
    if ((int)res.size() != n) { printf("NO\n"); return 0; }
    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        printf("%d", res[i]);
    }
    printf("\n");
    return 0;
}
